using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.UI;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;
[InitializeOnLoad] public static class KeyConfigChecks {
 const string Pending="KeyConfigPlayQA";static List<string> rows;static int count,stage;static string report,folder;static TrainingOverlay hud;static Keyboard keyboard;static Gamepad pad;static InputSettings old,temp;static IDisposable service;static TrainingApprovedCharacter original,other;static float start;static int baseline;static string inputBefore,charBefore;static double deadline;
 static KeyConfigChecks(){if(SessionState.GetBool(Pending,false))EditorApplication.update+=Tick;}
 static void Check(bool ok,string text){rows.Add((ok?"PASS ":"FAIL ")+text);if(!ok)throw new Exception(text);count++;}
 static Button Button(string name)=>Resources.FindObjectsOfTypeAll<Button>().First(b=>b.gameObject.scene.IsValid()&&b.name==name);
 static void Click(string name)=>Button(name).onClick.Invoke();static void Pump()=>hud.SendMessage("UpdateKeyConfig",SendMessageOptions.DontRequireReceiver);
 static void Keys(params Key[] keys){InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys));InputSystem.Update();}
 static void Pad(GamepadState state){InputSystem.QueueStateEvent(pad,state);InputSystem.Update();}
 static void CaptureKey(string id,Key key){Keys();Pad(new GamepadState());hud.StartKeyCapture(id);Pump();Keys(key);Pump();Keys();Pump();}
 public static void Run(){EditorSceneManager.OpenScene("Assets/Shioka/Scenes/CombatFormulaComparison.unity");SessionState.SetBool(Pending,true);EditorApplication.update-=Tick;EditorApplication.update+=Tick;EditorApplication.EnterPlaymode();}
 static void Setup(){rows=new List<string>();count=0;var args=Environment.GetCommandLineArgs();int ri=Array.IndexOf(args,"-keyConfigReport");report=ri<0?"Temp/keyconfig.txt":args[ri+1];folder=Path.Combine(Path.GetTempPath(),"Shioka-KeyConfig-QA-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);deadline=EditorApplication.timeSinceStartup+90;hud=UnityEngine.Object.FindAnyObjectByType<TrainingOverlay>();original=hud.player.InputCharacter;inputBefore=File.ReadAllText(AssetDatabase.GetAssetPath(Resources.Load<TrainingInputConfig>("TrainingInputConfig")));charBefore=File.ReadAllText(AssetDatabase.GetAssetPath(original));var defaults=KeyConfigProfile.Defaults(Resources.Load<TrainingInputConfig>("TrainingInputConfig"));Models(defaults);service=KeyConfigService.UseForTests(defaults,new KeyConfigStore(Path.Combine(folder,"ui.json")));hud.ReloadUserInput();old=InputSystem.settings;temp=UnityEngine.Object.Instantiate(old);temp.updateMode=InputSettings.UpdateMode.ProcessEventsManually;temp.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;temp.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;InputSystem.settings=temp;keyboard=InputSystem.AddDevice<Keyboard>();pad=InputSystem.AddDevice<Gamepad>();hud.SetOptionVisible(true);hud.ShowInputOptions(true);Keys();Pad(new GamepadState());Capture();Navigation();stage=0;}
 static void Navigation(){var nav=UnityEngine.Object.FindAnyObjectByType<TrainingOptionNavigation>();hud.RefreshMotionLayout(1280,720);var panel=Button("NavTraining").transform.parent as RectTransform;var size=panel.sizeDelta;hud.ShowTrainingOptions(true);hud.RefreshMotionLayout(1280,720);Check(panel.sizeDelta==size,"shared shell unchanged Training vs KeyConfig");nav.SelectByName("Position2");nav.MoveSelection(Vector2.down);Check(nav.FocusedName=="DisplayCommands","adjacent row preserves nearest column");nav.MoveSelection(Vector2.down);Check(nav.FocusedName=="Recover0","three columns to two columns never skips row");nav.MoveSelection(Vector2.left);Check(nav.FocusedName=="HP0","left remains same row");nav.MoveSelection(Vector2.down);Check(nav.FocusedName=="TG0","down moves nearest row in same column");nav.SelectByName("Fixed1");Canvas.ForceUpdateCanvases();var item=Button("Fixed1");var scroll=item.GetComponentInParent<ScrollRect>();var bounds=RectTransformUtility.CalculateRelativeRectTransformBounds(scroll.viewport,item.transform);Check(bounds.min.y>=scroll.viewport.rect.yMin-1&&bounds.max.y<=scroll.viewport.rect.yMax+1,"offscreen selected row revealed");hud.ShowInputOptions(true);hud.RefreshMotionLayout(1280,720);var key=Button("KeyRow_battle.J").GetComponentInParent<ScrollRect>();Check(key.viewport.rect.height>480,"KeyConfig viewport uses shared tall shell");nav.SelectByName("KeyRow_battle.Z");nav.MoveSelection(Vector2.down);Check(nav.FocusedName=="KeyRow_battle.Hold","adjacent single-column key row");hud.RefreshMotionLayout(640,360);Check(panel.sizeDelta.x*panel.localScale.x<=616.1f&&panel.sizeDelta.y*panel.localScale.y<=336.1f,"small viewport shell stays within safe bounds");hud.RefreshMotionLayout(1280,720);nav.SelectByName("NavDummy");nav.MoveSelection(Vector2.down);Check(nav.FocusedName=="NavInputs","sidebar stays in sidebar");}
 static void Models(KeyConfigProfile defaults){Check(defaults.Validate(out var error),"defaults valid "+error);var draft=defaults.Copy();string before=JsonUtility.ToJson(draft);Check(!draft.TryBinding("battle.J",false,"<Keyboard>/k",false,out var conflict,out error)&&conflict=="battle.K"&&error==null,"swap request identifies context conflict");Check(JsonUtility.ToJson(draft)==before,"declined/unapproved exchange leaves draft intact");Check(draft.TryBinding("battle.J",false,"<Keyboard>/k",true,out conflict,out error),"approved same-column swap");Check(draft.Row("battle.K").keyboard=="<Keyboard>/j"&&draft.Row("battle.J").pad==defaults.Row("battle.J").pad,"swap exchanges only device column");Check(draft.TryBinding("battle.J",false,"<Keyboard>/k",false,out _,out error)&&draft.Row("battle.J").keyboard=="","same-cell value clears");Check(draft.TryBinding("menu.Confirm",false,"<Keyboard>/i",false,out conflict,out error),"Menu vs Battle sharing allowed");Check(!draft.TryBinding("battle.J",true,"<Gamepad>/leftShoulder",true,out _,out error),"trigger overlap rejected without invalid exchange");Check(defaults.Row("battle.A").pad=="T1+<Gamepad>/buttonWest"&&defaults.Row("battle.J").pad=="<Gamepad>/buttonWest","button and modified button distinct");
 var store=new KeyConfigStore(Path.Combine(folder,"model.json"));Check(store.Load(defaults,out var status).Row("battle.J").keyboard==defaults.Row("battle.J").keyboard,"no-file defaults fallback");Check(store.Save(draft,out error),"atomic profile save");var loaded=new KeyConfigStore(store.Path).Load(defaults,out status);Check(loaded.Row("battle.K").keyboard==draft.Row("battle.K").keyboard,"fresh store/cold-load persists binding");Check(store.Save(defaults,out error)&&File.Exists(store.Path+".bak"),"second save preserves backup");File.WriteAllText(store.Path,"broken json");Check(store.Load(defaults,out status).Row("battle.J").keyboard==defaults.Row("battle.J").keyboard&&File.ReadAllText(store.Path)=="broken json","broken profile fallback without overwriting damaged data");var future=defaults.Copy();future.version=99;File.WriteAllText(store.Path,JsonUtility.ToJson(future));Check(store.Load(defaults,out status).version==1,"unsupported version fallback");var invalid=defaults.Copy();invalid.bindings[0].id="unknown";Check(!invalid.Validate(out error),"unknown stable action ID rejected");
 var charDraft=defaults.Copy();var lp=original.attackSlots.Single(x=>x.assigned&&x.command==TrainingCommand.Light);var physical=JsonUtility.ToJson(new BindingBox{rows=charDraft.bindings});charDraft.SwapOperation(original,KeyConfigProfile.OpId(lp),0);Check(charDraft.Slot(original,lp)==0&&physical==JsonUtility.ToJson(new BindingBox{rows=charDraft.bindings}),"character swap never edits physical bindings");}
 [Serializable] sealed class BindingBox{public KeyBindingRow[] rows;}
 static void Capture(){using(var c=new KeyBindingCapture(hud.KeyConfigDraft,false)){c.Tick();Pad(new GamepadState{leftStick=new Vector2(.9f,.8f)});c.Tick();Check(!c.Complete,"stick noise not captured");Pad(new GamepadState{leftTrigger=.3f});c.Tick();Check(!c.Complete,"partial trigger noise not captured");Pad(new GamepadState{leftTrigger=1});c.Tick();Check(!c.Complete,"captured trigger waits release");Pad(new GamepadState());c.Tick();Check(c.Complete&&c.Pad&&c.Value=="<Gamepad>/leftTrigger","L2 trigger capture");}
 using(var c=new KeyBindingCapture(hud.KeyConfigDraft,false)){c.Tick();Pad(new GamepadState().WithButton(GamepadButton.LeftShoulder));c.Tick();Check(!c.Complete,"T1 alone not prematurely committed");Pad(new GamepadState().WithButton(GamepadButton.LeftShoulder).WithButton(GamepadButton.RightShoulder));c.Tick();Pad(new GamepadState());c.Tick();Check(c.Complete&&c.Value=="T1+<Gamepad>/rightShoulder","T1 chord capture");}
 Keys(Key.Escape);using(var c=new KeyBindingCapture(hud.KeyConfigDraft,false)){c.Tick();Check(!c.Complete,"opening held Esc not captured");Keys();c.Tick();Keys(Key.Escape);c.Tick();Keys();c.Tick();Check(c.Complete&&c.Value=="<Keyboard>/escape","Esc assignable after neutral");}
 using(var c=new KeyBindingCapture(hud.KeyConfigDraft,false)){c.Tick();Pad(new GamepadState().WithButton(GamepadButton.North));c.Tick();InputSystem.RemoveDevice(pad);pad=null;c.Tick();Check(!c.Complete,"disconnect cancels candidate safely");}pad=InputSystem.AddDevice<Gamepad>();Pad(new GamepadState());}
 static void UI(){Check(Button("BasicTab").GetComponentInChildren<Text>().text=="基本キー設定"&&Button("CharacterTab").GetComponentInChildren<Text>().text==original.characterName,"Battle tab labels");Check(Button("KeyRow_battle.J").GetComponentInChildren<Text>().text=="J〔弱P〕","basic row shows operation without repeating character");CaptureKey("battle.J",Key.K);Check(hud.KeyConfigConfirmVisible,"capture opens exchange confirmation");Click("No");Check(hud.KeyConfigDraft.Row("battle.J").keyboard=="<Keyboard>/j","exchange cancel unchanged");CaptureKey("battle.J",Key.K);Click("Yes");Check(hud.KeyConfigDraft.Row("battle.J").keyboard=="<Keyboard>/k"&&hud.KeyConfigDraft.Row("battle.K").keyboard=="<Keyboard>/j","exchange approval updates draft only");Check(KeyConfigService.Ensure().Row("battle.J").keyboard=="<Keyboard>/j","draft not applied before save");CaptureKey("battle.J",Key.K);Check(hud.KeyConfigDraft.Row("battle.J").keyboard=="","same capture clears current cell");Click("CancelKeys");CaptureKey("battle.J",Key.N);Click("SaveKeys");Check(KeyConfigService.Ensure().Row("battle.J").keyboard=="<Keyboard>/n"&&File.Exists(Path.Combine(folder,"ui.json")),"UI saves user profile and applies");var cold=new KeyConfigStore(Path.Combine(folder,"ui.json")).Load(KeyConfigService.Defaults(),out _);Check(cold.Row("battle.J").keyboard=="<Keyboard>/n","UI saved profile loads in fresh reader");Click("CharacterTab");Check(!Button("KeyRow_battle.J").gameObject.activeSelf&&Button("KeyRow_menu.Confirm").gameObject.activeSelf,"character tab changes Battle only");var lp=original.attackSlots.Single(x=>x.assigned&&x.command==TrainingCommand.Light);int index=Array.IndexOf(original.attackSlots,lp);Click("Operation"+index);Click("SlotChoice0");Click("Yes");Check(hud.KeyConfigDraft.Slot(original,lp)==0&&hud.KeyConfigDraft.Row("battle.J").keyboard=="<Keyboard>/n","character UI changes slot, not physical binding");Click("SaveKeys");Check(KeyConfigService.ResolveSlots(original).Single(x=>x.command==TrainingCommand.Light&&x.assigned).slot==BattleAttackSlot.A&&lp.slot==BattleAttackSlot.J,"character preference applied without authoring write");other=UnityEngine.Object.Instantiate(original);other.characterId="qa.other";other.characterName="検証キャラ";hud.player.GetComponent<ArmoredStaticPoseView>().characterProfile=other;Pump();Check(Button("CharacterTab").GetComponentInChildren<Text>().text=="検証キャラ","selected character updates tab");Check(KeyConfigService.ResolveSlots(other).Single(x=>x.assigned&&x.command==TrainingCommand.Light).slot==BattleAttackSlot.J,"other character layout independent");hud.player.GetComponent<ArmoredStaticPoseView>().characterProfile=original;UnityEngine.Object.Destroy(other);other=null;Pump();Click("BasicTab");CaptureKey("battle.J",Key.Q);Check(hud.KeyConfigDraft.Row("battle.J").keyboard=="<Keyboard>/q","basic edit retained across tabs");Click("DefaultKeys");Check(hud.KeyConfigDraft.Row("battle.J").keyboard=="<Keyboard>/j"&&KeyConfigService.Ensure().Row("battle.J").keyboard=="<Keyboard>/n","defaults are draft until save");Click("CancelKeys");Check(hud.KeyConfigDraft.Row("battle.J").keyboard=="<Keyboard>/n","cancel reloads applied profile");Click("DefaultKeys");Click("SaveKeys");Check(KeyConfigService.ResolveSlots(original).Single(x=>x.assigned&&x.command==TrainingCommand.Light).slot==BattleAttackSlot.J,"restore defaults clears character override");hud.StartKeyCapture("battle.J");Click("CancelCapture");Check(!hud.KeyConfigCapturing,"mouse cancel route remains available");Check(Button("MouseOptions").gameObject.activeSelf&&Button("BackKeys").interactable,"mouse Option/back recovery exists");Keys(Key.J);baseline=hud.player.InputBuffer.History.Count(x=>x.Command==TrainingCommand.Light);hud.SetOptionVisible(false);start=Time.fixedTime;stage=1;}
 static void CapturePanel(int width,int height){var cam=hud.HudCamera;var previous=cam.targetTexture;var active=RenderTexture.active;var target=new RenderTexture(width,height,24);target.Create();try{cam.targetTexture=target;hud.LayoutHud(width,height);hud.RefreshMotionLayout(width,height);Canvas.ForceUpdateCanvases();cam.Render();RenderTexture.active=target;var image=new Texture2D(width,height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,width,height),0,0);image.Apply();File.WriteAllBytes(Path.ChangeExtension(report,null)+"-"+width+".png",image.EncodeToPNG());UnityEngine.Object.Destroy(image);}finally{cam.targetTexture=previous;RenderTexture.active=active;target.Release();UnityEngine.Object.Destroy(target);hud.LayoutHud(Screen.width,Screen.height);hud.RefreshMotionLayout(Screen.width,Screen.height);}}
 static void Tick(){try{if(!EditorApplication.isPlaying||Time.frameCount<5)return;if(rows==null){Setup();return;}InputSystem.Update();if(stage==0){CapturePanel(1280,720);CapturePanel(640,360);UI();return;}if(EditorApplication.timeSinceStartup>deadline)throw new Exception("KeyConfig acceptance timeout");float frames=(Time.fixedTime-start)/Time.fixedDeltaTime;if(stage==1&&frames>=3){Check(hud.player.InputBuffer.History.Count(x=>x.Command==TrainingCommand.Light)==baseline,"captured/closing J does not leak attack");Keys();start=Time.fixedTime;stage=2;}else if(stage==2&&frames>=3){Keys(Key.J);start=Time.fixedTime;stage=3;}else if(stage==3&&frames>=2){Check(hud.player.InputBuffer.History.Any(x=>x.Command==TrainingCommand.Light),"fresh gameplay input works after KeyConfig closes");Check(inputBefore==File.ReadAllText(AssetDatabase.GetAssetPath(Resources.Load<TrainingInputConfig>("TrainingInputConfig")))&&charBefore==File.ReadAllText(AssetDatabase.GetAssetPath(original)),"authoring SOs unchanged by personal settings");Finish(0);}}catch(Exception e){rows?.Add("EXCEPTION "+e);Debug.LogException(e);Finish(1);}}
 static void Finish(int exit){SessionState.SetBool(Pending,false);EditorApplication.update-=Tick;hud?.CancelKeyCapture();if(other!=null&&hud!=null)hud.player.GetComponent<ArmoredStaticPoseView>().characterProfile=original;service?.Dispose();if(keyboard!=null)InputSystem.RemoveDevice(keyboard);if(pad!=null)InputSystem.RemoveDevice(pad);if(old!=null)InputSystem.settings=old;if(temp!=null)UnityEngine.Object.DestroyImmediate(temp);Time.timeScale=1;if(rows!=null){rows.Add(count+" PASS; exit="+exit+"; scripted UI + virtual devices, not physical clicks");rows.Add("Test profile recovery directory: "+folder);File.WriteAllLines(report,rows);}EditorApplication.Exit(exit);}
}
